export const tabs=[['strategy','01','제작 설계'],['direction','02','취향 보드'],['concepts','03','콘셉트 비교'],['storyboard','04','장면 구성'],['review','05','영상 확인'],['history','06','이력·납품']];
const stages={received:'접수',planning:'내용·일정 협의',producing:'제작 중',review:'시안 확인',delivered:'최종 전달',archived:'보관됨'};
