const STAGE={
  strategy:{no:'01',en:'CREATIVE STRATEGY',word:'설계',art:'stage-strategy',w:387,h:397,title:['만들기 전에,','같은 목표를 봐요.'],text:'아는 내용만 적고 나머지는 비워 둬도 괜찮아요. 메시지·근거·행동은 담당자가 정리해서 제안해요.'},
  direction:{no:'02',en:'REFERENCE BOARD',word:'취향',art:'stage-direction',w:443,h:379,title:['어떤 광고를','떠올리고 있나요?'],text:'좋아하는 느낌과 꼭 담을 이야기를 알려 주세요. 참고자료는 어디가 좋은지 한 줄만 적어 줘도 큰 도움이 돼요.'},
  concepts:{no:'03',en:'CONCEPTS',word:'콘셉트',art:'stage-concepts',w:226,h:344,title:['같은 목표,','다른 표현.'],text:'이미지와 이야기를 나란히 비교해 보세요. 고른 콘셉트와 의견은 담당자에게 그대로 전달돼요.'},
  storyboard:{no:'04',en:'STORYBOARD',word:'장면',art:'stage-storyboard',w:403,h:391,title:['광고의 흐름을','미리 보세요.'],text:'장면마다 무엇을 보여 주고 어떤 문구가 나오는지 확인해 주세요. 그림이 아직 없는 장면도 설명으로 먼저 볼 수 있어요.'},
  review:{no:'05',en:'VIDEO REVIEW',word:'영상',art:'stage-review',w:383,h:416,title:['이제 영상으로','확인해요.'],text:'영상을 멈추고 의견을 쓰면 그 장면의 시간이 같이 붙어요. 수정본은 이전 시안과 나란히 볼 수 있어요.'},
  history:{no:'06',en:'DELIVERY & HISTORY',word:'납품',art:'stage-history',w:404,h:372,title:['함께 정한 이야기가','남아요.'],text:'고른 것과 남긴 의견, 승인한 시안, 최종 파일이 모두 여기 모여 있어요.'},
  manage:{no:'↗',en:'PROJECT SETTINGS',word:'관리',art:'',title:['고객과의 약속을','정리해요.'],text:'단계와 전달일, 고객이 다음에 할 일을 적고 초대 링크를 만들어요.'}
};
const field=(label,name,value='',type='text',{required=false,max=3000,placeholder='',help='',attrs=''}={})=>`<label class="field">${esc(label)}${type==='textarea'?`<textarea name="${esc(name)}" rows="3" maxlength="${max}" placeholder="${esc(placeholder)}" ${required?'required':''}>${esc(value)}</textarea>`:`<input name="${esc(name)}" type="${type}" value="${type==='file'?'':esc(value)}" ${type==='file'?'accept="image/png,image/jpeg"':`maxlength="${max}"`} placeholder="${esc(placeholder)}" ${required?'required':''} ${attrs}>`}${help?`<small>${esc(help)}</small>`:''}</label>`;
const btn=(text,action,extra='',cls='')=>`<button type="button" class="button ${cls}" data-action="${esc(action)}" ${extra}>${esc(text)}</button>`;
const submit=(text='저장')=>`<button type="submit" class="button primary" data-mutate>${esc(text)}</button>`;
const targetAttrs=(id)=>`data-id="${esc(id)}"`;
const imageSource=item=>safeUrl(item?.media?.url||item?.imageUrl||'',{media:!!item?.media});
const emptyVisual=label=>`<div class="empty-visual"><div><svg viewBox="0 0 40 40" aria-hidden="true"><rect x="3" y="5" width="34" height="29" rx="4"/><circle cx="13" cy="14" r="3"/><path d="m4 28 9-8 7 6 6-10 10 14"/></svg>${esc(label)}</div></div>`;
const visual=(item,cls='concept-image')=>imageSource(item)?`<button type="button" class="${cls}" data-action="image" data-src="${esc(imageSource(item))}" data-label="${esc(item.title||item.label||'참고 이미지')}"><img src="${esc(imageSource(item))}" alt="${esc(item.title||item.label||'참고 이미지')}" loading="lazy" referrerpolicy="${new URL(imageSource(item)).origin!==location.origin?'origin':'no-referrer'}"></button>${item.imageUrl&&safeUrl(item.imageUrl)?`<a class="text-button image-source-link" href="${esc(safeUrl(item.imageUrl))}" target="_blank" rel="noopener noreferrer">원본 이미지 열기 ↗</a>`:''}`:emptyVisual('이미지를 준비하고 있어요');
// 단계 머리는 projectView의 포스터가 맡는다. 탭 안에는 제작자용 도구 단추만 남긴다.
// 내려받을 때 파일 이름을 「프로젝트_버전.확장자」로(제작자가 올린 원래 이름 대신).
const downloadName=(p,v)=>{const ext=(String(v?.media?.fileName||'').match(/\.([A-Za-z0-9]{2,5})$/)?.[1]||({'video/mp4':'mp4','video/webm':'webm','image/png':'png','image/jpeg':'jpg'}[v?.media?.mimeType]||'bin')).toLowerCase();return `${p?.title||'PULSE'}_${v?.label||'파일'}`.replace(/[\\/:*?"<>|]+/g,' ').replace(/\s+/g,' ').trim().slice(0,120)+'.'+ext;};
const tools=action=>action?`<div class="stage-tools">${action}</div>`:'';
const pageIntro=(eyebrow,title,description,action='')=>`<header class="section-intro page-intro"><div><span class="eyebrow">${esc(eyebrow)}</span><h2>${esc(title)}</h2><p>${esc(description)}</p></div>${action}</header>`;
const studio=p=>p?.studio||{preferences:{},assets:[],references:[],concepts:[],scenes:[],sceneReviews:[],comments:[]};
const isImage=asset=>asset?.mimeType?.startsWith('image/');
const assetFields=(s,item={})=>`${field('새 이미지 올리기','file','','file',{help:'PNG·JPEG, 100MB까지. 이미 올린 이미지는 아래에서 다시 고를 수 있어요.'})}<label class="field">이미 올린 이미지<select name="assetId"><option value="">선택하지 않음</option>${(s.assets||[]).filter(isImage).map(a=>`<option value="${esc(a.id)}" ${item.assetId===a.id?'selected':''}>${esc(a.fileName)}</option>`).join('')}</select></label>${field('또는 이미지 주소','imageUrl',item.imageUrl||'','url',{max:2000,placeholder:'https://…',help:'고객도 열 수 있는 주소여야 해요.'})}`;
const visibility=value=>`<label class="field">공개 범위<select name="visibility"><option value="internal" ${value!=='customer'?'selected':''}>제작자만 보기 · 준비 중</option><option value="customer" ${value==='customer'?'selected':''}>고객에게 보이기</option></select></label>`;
